B.bcf=new A.em("sargelu","Sargelu",B.jT,"Middle Jurassic \xb7 Bajocian \u2013 Callovian",B.zc,B.hj,B.aw,62,"\u062d\u062c\u0631 \u062c\u064a\u0631\u064a \u0648\u0634\u064a\u0644 \u0645\u062a\u062f\u0627\u062e\u0644\u0629. \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0623\u0639\u0644\u0649 \u062c\u064a\u0631 \u0637\u064a\u0646\u064a \u062c\u062f\u0627\u064b\u060c \u0648\u0627\u0644\u0623\u0633\u0641\u0644 \u0634\u064a\u0644 \u0643\u0644\u0633\u064a \u062c\u062f\u0627\u064b \u0648\u064a\u0647 \u0639\u0631\u0648\u0642 \u062c\u064a\u0631.","Interbedded limestone and shale. The upper part is highly argillaceous limestone; the lower part highly calcareous shale with limestone streaks.","\u0638\u0647\u0648\u0631 \u062d\u062c\u0631 \u062c\u064a\u0631\u064a \u0637\u064a\u0646\u064a \u0648\u064a\u0647 Slow ROP.","Argillaceous limestone with slow ROP.",B.cOi,B.cOl,null,null,null,null,"\u0645\u0643\u0645\u0646 \u0646\u0641\u0637\u064a \u0628\u0628\u0639\u0636 \u0627\u0644\u062d\u0642\u0648\u0644.","Oil reservoir in some fields.",null,null)
